arguments.command:
python3 -I -c 'import json, pathlib, collections; f=pathlib.Path("/workspace/incident/run/events.jsonl"); counts=collections.Counter(); metrics=[]; aborts=[]; reads=[]; kinds=collections.Counter();
with f.open() as s:
 for line in s:
  try: e=json.loads(line)
  except Exception: continue
  k=e.get("kind",e.get("event")); kinds[k]+=1
  if k=="read":
   counts[(e.get("step"),e.get("difficulty"),e.get("outcome"))]+=1
   if e.get("outcome")!="ok": aborts.append({x:e.get(x) for x in ("step","id","difficulty","path","outcome","error")})
  if k=="rollout_end": metrics.append((e.get("step"),e.get("metrics")))
print("event kinds",kinds); print("read counts",sorted(counts.items(),key=str)); print("non-ok reads",aborts[:10],"total",len(aborts)); print("rollout metrics");
for step,m in metrics: print(step,{k:v for k,v in (m or {}).items() if k in ("data/read_attempts","data/abort_count","data/admitted_count","data/admitted_hard_fraction","data/survivor_reward_mean","data/reward_per_read_attempt")})'

